use oxc_allocator::Allocator;
use oxc_parser::Parser;
use oxc_parser::config::TokensParserConfig;
use oxc_span::SourceType;
use vize_canon::{
    ContentMapperDiagnosticDirective, ContentMapperDiagnosticDirectives, ContentMapperSpan,
    ContentMapperTransform,
};

use super::compact::compact;

fn transform(text: &str, spans: Vec<ContentMapperSpan>) -> ContentMapperTransform {
    ContentMapperTransform {
        text: text.into(),
        extension: ".tsx",
        mappings: spans,
        semantic_links: Vec::new(),
        diagnostic_directives: None,
        diagnostics: Vec::new(),
    }
}

/// Each token's text, whether a line break precedes it, and the directive
/// comment (`@ts-…` prefix) that precedes it, if any.
fn tokens(text: &str) -> Vec<(&str, bool, Option<&'static str>)> {
    let allocator = Allocator::default();
    let parsed = Parser::new(&allocator, text, SourceType::tsx())
        .with_config(TokensParserConfig)
        .parse();
    assert!(parsed.diagnostics.is_empty(), "{text}");
    let mut comments = parsed.program.comments.iter().peekable();
    parsed
        .tokens
        .iter()
        .map(|token| {
            let mut directive = None;
            while let Some(comment) = comments.next_if(|c| c.span.end <= token.start()) {
                let range = comment.span.start as usize..comment.span.end as usize;
                let body = text.get(range).unwrap();
                let body = body.trim_start_matches('/').trim_start();
                for name in ["@ts-ignore", "@ts-expect-error"] {
                    if body.starts_with(name) {
                        directive = Some(name);
                    }
                }
            }
            let range = token.start() as usize..token.end() as usize;
            (text.get(range).unwrap(), token.is_on_new_line(), directive)
        })
        .collect()
}

/// Compact `text` and check what TypeScript reads did not move.
fn compacted(text: &str, spans: Vec<ContentMapperSpan>) -> ContentMapperTransform {
    let mut result = transform(text, spans.clone());
    compact(&mut result);
    assert_eq!(tokens(&result.text), tokens(text), "{}", result.text);
    for (before, after) in spans.iter().zip(&result.mappings) {
        let (start, len) = (before.0[0], before.0[1]);
        assert_eq!(
            result.text.get(after.0[0]..after.0[0] + len),
            text.get(start..start + len)
        );
    }
    result
}

#[test]
fn notes_banners_and_indentation_collapse_to_line_breaks() {
    let text = "// ====\n// Generated by vize\n// ====\n\nfunction f() {\n  // @vize-map: expr -> 1:2\n  void a; // VBind\n\n    if (a) {\n      g(); // handler expression\n    }\n}\n";
    let result = compacted(text, Vec::new());
    assert_eq!(
        result.text,
        "function f() {\nvoid a;\nif (a) {\ng();\n}\n}\n"
    );
}

#[test]
fn directive_like_comments_stay_and_ts_ignore_keeps_only_its_directive() {
    let text = "/// <reference lib=\"dom\" />\n// @ts-nocheck\nlet a = 1;\n  // @ts-ignore Inference-only guard; authored checks own diagnostics.\n  a = 2;\n  // @ts-expect-error kept verbatim\n  a = 3;\n  /* block */ a = 4;\n  //# sourceMappingURL=x\n  // @jsx h\n";
    let result = compacted(text, Vec::new());
    assert_eq!(
        result.text,
        "/// <reference lib=\"dom\" />\n// @ts-nocheck\nlet a = 1;\n// @ts-ignore\na = 2;\n// @ts-expect-error kept verbatim\na = 3;\n/* block */ a = 4;\n//# sourceMappingURL=x\n// @jsx h\n"
    );
}

#[test]
fn strings_templates_and_regexes_are_code() {
    let text = "const s = `\n  // not a comment\n    ${a} // still text ${`\n  // nested\n`}\n`;\nconst t = \"a // b\" + 'c';\nconst r = /\\/\\/ x[/]/g;\nconst q = a / 2 / `${{ k: 1 }}`;\n  // note\nvoid s;\n";
    let result = compacted(text, Vec::new());
    assert_eq!(
        result.text,
        "const s = `\n  // not a comment\n    ${a} // still text ${`\n  // nested\n`}\n`;\nconst t = \"a // b\" + 'c';\nconst r = /\\/\\/ x[/]/g;\nconst q = a / 2 / `${{ k: 1 }}`;\nvoid s;\n"
    );
}

#[test]
fn trivia_a_span_covers_stays() {
    let text = "let a = 1;\n  // user comment\n  let b = 2;\n  // generated note\n  let c = 3;\n";
    let user = text.find("let a").unwrap();
    let user_end = text.find("let b = 2;").unwrap() + "let b = 2;".len();
    let span = ContentMapperSpan([user, user_end - user, 7, user_end - user, 0, 0]);
    let result = compacted(text, vec![span]);
    assert_eq!(
        result.text,
        "let a = 1;\n  // user comment\n  let b = 2;\nlet c = 3;\n"
    );
}

#[test]
fn spans_and_directives_move_with_the_text() {
    let text = "  // note\n  foo(bar);\n  // @vize-map: expr -> 4:7\n  baz;\n";
    let foo = text.find("foo").unwrap();
    let bar = text.find("bar").unwrap();
    let baz = text.find("baz").unwrap();
    let spans = vec![
        ContentMapperSpan([foo, 3, 0, 3, 0, 0]),
        ContentMapperSpan([bar, 3, 4, 3, 1, 0]),
        ContentMapperSpan([baz, 3, 8, 3, 0, 0]),
    ];
    let mut result = transform(text, spans.clone());
    result.diagnostic_directives = Some(ContentMapperDiagnosticDirectives {
        unused_expect_directive_diagnostics: Vec::new(),
        directives: vec![
            // The gap between `bar)` and `baz`: `;`, a note and indentation.
            ContentMapperDiagnosticDirective([0, 0, bar + 4, baz, 0, 0]),
            ContentMapperDiagnosticDirective([8, 3, baz, baz + 3, 1, 0]),
        ],
    });
    compact(&mut result);
    assert_eq!(result.text, "foo(bar);\nbaz;\n");
    let moved: Vec<_> = result.mappings.iter().map(|span| span.0[0]).collect();
    assert_eq!(moved, [0, 4, 10]);
    let directives = &result.diagnostic_directives.unwrap().directives;
    assert_eq!(directives[0].0[2..4], [8, 10]);
    assert_eq!(directives[1].0[2..4], [10, 13]);
    assert_eq!(compacted(text, spans).text, "foo(bar);\nbaz;\n");
}

#[test]
fn uncertain_projections_stay_whole() {
    for text in [
        // JSX text, which a scan cannot tell from code.
        "const j = <div>\n  // jsx text\n</div>;\n  // note\n",
        "/// <reference types=\"vue/jsx\" />\nconst j = <br />;\n  // note\n",
        // A `/` after `)` or `}` may start a regular expression.
        "if (a) /x/.test(b);\n  // note\n",
        "{}\n/x/.test(b);\n  // note\n",
        "#!/usr/bin/env node\n  // note\nlet a;\n",
        "let s = \"unterminated\n  // note\n",
        // U+2028 ends a `//` comment in JavaScript; the code after it is not trivia.
        "let a; // note\u{2028}let b;\n  // note\n",
    ] {
        let mut result = transform(text, Vec::new());
        compact(&mut result);
        assert_eq!(result.text, text);
    }
}

#[test]
fn a_line_break_survives_every_collapse() {
    // ASI: `a` and `b` stay separate statements, `return` keeps its line.
    let text = "let a = 1\n  // note\nlet b = a\nfunction f() {\n  return // why\n  a\n}\n";
    let result = compacted(text, Vec::new());
    assert_eq!(
        result.text,
        "let a = 1\nlet b = a\nfunction f() {\nreturn\na\n}\n"
    );
}

#[test]
fn geometry_only_hosts_get_continuing_verbatim_runs_joined() {
    let mut spans = vec![
        ContentMapperSpan([0, 3, 10, 3, 0, 7]),
        // Continues in both texts: joined, whatever the features.
        ContentMapperSpan([3, 2, 13, 2, 0, 0]),
        // A gap in the authored text: kept apart.
        ContentMapperSpan([5, 1, 16, 1, 0, 0]),
        // An atom: kept apart, and so is the verbatim span after it.
        ContentMapperSpan([6, 1, 17, 1, 1, 0]),
        ContentMapperSpan([7, 2, 18, 2, 0, 0]),
    ];
    super::compact::join_verbatim_runs(&mut spans);
    assert_eq!(
        spans,
        [
            ContentMapperSpan([0, 5, 10, 5, 0, 7]),
            ContentMapperSpan([5, 1, 16, 1, 0, 0]),
            ContentMapperSpan([6, 1, 17, 1, 1, 0]),
            ContentMapperSpan([7, 2, 18, 2, 0, 0]),
        ]
    );
}

/// The scan against oxc on every projection the repository pins: it either
/// gives up or finds exactly the parser's token gaps and comments.
#[test]
fn the_trivia_scan_agrees_with_oxc_on_pinned_projections() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let mut texts = Vec::new();
    for (dir, suffix) in [
        ("tests/_fixtures/differential/lsp", ".virtual.ts.txt"),
        ("crates/vize_maestro/tests/fixtures", ".virtual.ts.txt"),
        ("crates/vize_canon/snapshots", ".snap"),
    ] {
        let mut stack = vec![root.join(dir)];
        while let Some(dir) = stack.pop() {
            for entry in std::fs::read_dir(&dir).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    stack.push(path);
                } else if path.to_string_lossy().ends_with(suffix) {
                    let text = std::fs::read_to_string(&path).unwrap();
                    // An insta snapshot holds its value after the `---` header.
                    let body = match text.strip_prefix("---\n") {
                        Some(rest) => rest.split_once("\n---\n").map_or(rest, |(_, body)| body),
                        None => text.as_str(),
                    };
                    texts.push((path, body.to_owned()));
                }
            }
        }
    }
    let mut agreed = 0;
    for (path, text) in &texts {
        let allocator = Allocator::default();
        let parsed = Parser::new(&allocator, text, SourceType::tsx())
            .with_config(TokensParserConfig)
            .parse();
        if parsed.panicked || !parsed.diagnostics.is_empty() {
            continue;
        }
        let (mut scanned, mut scanned_comments) = (Vec::new(), Vec::new());
        let scan = super::trivia_scan::trivia(text, |start, end, comments| {
            scanned.push((start, end));
            scanned_comments.extend(comments.iter().map(|c| (c.start, c.end)));
        });
        if scan.is_none() {
            continue;
        }
        let mut gaps = Vec::new();
        let mut previous = 0;
        let ends = parsed
            .tokens
            .iter()
            .map(|t| (t.start() as usize, t.end() as usize));
        for (start, end) in ends.chain(std::iter::once((text.len(), text.len()))) {
            if start > previous {
                gaps.push((previous, start));
            }
            previous = end.max(previous);
        }
        let comments: Vec<_> = parsed
            .program
            .comments
            .iter()
            .map(|c| (c.span.start as usize, c.span.end as usize))
            .collect();
        assert_eq!(scanned, gaps, "{}", path.display());
        assert_eq!(scanned_comments, comments, "{}", path.display());
        agreed += 1;
    }
    assert!(agreed >= texts.len() / 2, "{agreed} of {}", texts.len());
}
